package com.riderent;
import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;
@Component class SeedData implements CommandLineRunner {private final VehicleRepo vr;private final CustomerRepo cr;SeedData(VehicleRepo v,CustomerRepo c){vr=v;cr=c;}public void run(String... a){if(vr.count()==0){add("Royal Enfield Classic 350","Bike","Royal Enfield",899,2,"Manual");add("Honda Activa 6G","Scooter","Honda",499,2,"Automatic");add("Hyundai Creta","Car","Hyundai",2499,5,"Automatic");add("Maruti Swift","Car","Maruti Suzuki",1799,5,"Manual");}if(cr.count()==0){Customer c=new Customer();c.name="Demo Customer";c.email="demo@riderent.in";c.phone="9876543210";c.licenseNumber="DL-123456";cr.save(c);}}void add(String n,String t,String b,double p,int s,String tr){Vehicle v=new Vehicle();v.name=n;v.type=t;v.brand=b;v.pricePerDay=p;v.seats=s;v.transmission=tr;v.fuel="Petrol";v.status="ACTIVE";vr.save(v);}}
